'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto'),assert=require('node:assert/strict');
const PLAN={'3ff9d29693db3ad015bf6aa6':25.5,'69d3e2e4f0b486a7c84f7e82':25.5,'8ce903dcf33d5724497fc39b':5,'a842f7f290485451559b00ae':5,'0a0dcc18b9157d9284108d45':5,'5c57844f2bbf21e716d8be82':5,'46a1b35e72a0f9fd67aeb772':29,'5236162d076f5b12d308cab4':0,'6e294677d8bcff5c19987a49':0};
function apply(dataDir,expectedHash,reference){assert.ok(path.isAbsolute(dataDir));assert.match(expectedHash,/^[a-f0-9]{64}$/);assert.ok(reference);const file=path.join(dataDir,'register.json'),raw=fs.readFileSync(file);assert.equal(crypto.createHash('sha256').update(raw).digest('hex'),expectedHash,'Current data changed; re-inspect before applying');const old=JSON.parse(raw),before=old.companies.find(c=>c.slug==='horizon-network');assert.ok(!before.allocationCorrections?.includes(reference));const active=before.psc.filter(p=>!p.ceased);assert.deepEqual(active.map(p=>p.id).sort(),Object.keys(PLAN).sort(),'Unexpected holder identities');assert.equal(active.find(p=>p.id==='3ff9d29693db3ad015bf6aa6').name,'Charlie Livsey');assert.equal(active.find(p=>p.id==='0a0dcc18b9157d9284108d45').name,'Val G');assert.equal(active.find(p=>p.id==='46a1b35e72a0f9fd67aeb772').name,'Community Organisation');const filesDir=path.join(dataDir,'files'),priorFiles=new Set(fs.readdirSync(filesDir));process.env.COMPANIES_GROUP_UPDATES='off';process.env.COMPANIES_SEED='off';const s=require('../companies-site/lib/store'),voting=require('../companies-site/lib/founder-voting'),pdf=require('../companies-site/lib/pdf');
try{s.init(dataDir);const actor='owner-request:'+reference;for(const c of [...s.db.companies])if(c.shareModel!=='founder75')s.migrateFounderVoting(c.slug,actor);const c=s.company('horizon-network'),parent=s.company('hn-group'),date=new Date().toISOString().slice(0,10),at=new Date().toISOString();assert.ok(parent);const hng=c.psc.find(p=>p.id==='69d3e2e4f0b486a7c84f7e82');if(hng.notificationFiling&&!old.filings.some(f=>f.id===hng.notificationFiling)){const generated=s.db.filings.find(f=>f.id===hng.notificationFiling);if(generated){s.db.filings=s.db.filings.filter(f=>f.id!==generated.id);fs.rmSync(s.filePath(generated.file),{force:true});}delete hng.notificationFiling;}const policy=voting.setMinimum(c,{minimum:51,consent:reference},actor);c.founderVotingMinimum=51;c.votingPolicyHistory=policy.votingPolicyHistory;c.parent=parent.slug;
for(const p of c.psc.filter(p=>!p.ceased)){const n=PLAN[p.id],founder=['3ff9d29693db3ad015bf6aa6','69d3e2e4f0b486a7c84f7e82'].includes(p.id);p.share=String(n);p.classA=founder?n:'';p.classB=founder?'':n||'';p.classC='';p.classCIssuedBy='';if(p.id==='69d3e2e4f0b486a7c84f7e82'){p.name=parent.legalName;p.kind='Parent company';}}
const previousDelegations=structuredClone(c.votingDelegations||[]);c.delegationHistory=[...(c.delegationHistory||[]),...previousDelegations.map(entry=>({action:'revoke',holder:entry.holder,entry,at,by:actor,reference}))];c.votingDelegations=[];let next=voting.delegate(c,{action:'delegate',holder:'46a1b35e72a0f9fd67aeb772',name:'Dion McKew',kind:'Individual',percent:50},actor);next=voting.delegate(next,{action:'delegate',holder:'46a1b35e72a0f9fd67aeb772',name:'Evan Strong',kind:'Individual',percent:50,append:true},actor);c.votingDelegations=next.votingDelegations;c.delegationHistory=next.delegationHistory;
const calc=voting.calculation(c);for(const p of c.psc.filter(p=>!p.ceased)){const band=(n,label)=>n>=75?[label+' – 75% or more']:n>50?[label+' – more than 50% but less than 75%']:n>25?[label+' – more than 25% but not more than 50%']:[];p.control=[...(p.control||[]).filter(x=>!/^Ownership of (shares|voting rights)/.test(x)),...band(Number(p.share),'Ownership of shares'),...band(calc.holders[p.id].votes,'Ownership of voting rights')];}
assert.equal(calc.holders['3ff9d29693db3ad015bf6aa6'].votes,25.5);assert.equal(calc.holders['69d3e2e4f0b486a7c84f7e82'].votes,25.5);assert.equal(calc.holders['46a1b35e72a0f9fd67aeb772'].votes,0);for(const id of ['5236162d076f5b12d308cab4','6e294677d8bcff5c19987a49'])assert.equal(calc.holders[id].votes,14.5);assert.equal(c.psc.filter(p=>!p.ceased).reduce((n,p)=>n+Number(p.share),0),100);assert.equal(calc.controllers.reduce((n,p)=>n+p.votes,0),100);
c.capitalHistory=[...(c.capitalHistory||[]),{id:crypto.randomBytes(12).toString('hex'),at,action:'owner-allocation',reference,consent:reference,before:active,after:structuredClone(c.psc.filter(p=>!p.ceased))}];c.allocationCorrections=[...(c.allocationCorrections||[]),reference];c.updatedAt=at;
const made=[];function filing(code,category,description,rows){const spec={code,heading:description,company:c.legalName,number:c.number||'',date,rows:[['Company',c.legalName],['Owner written instruction',reference],...rows],footer:"Generated automatically by the Company Register run by HN Group Limited. This is a group register document, not a filing with the UK government's Companies House."};const f=s.addFiling(c.slug,{date,category,description,source:'generated'},pdf.build(spec),actor);f.doc={code,heading:description,company:c.legalName,number:c.number||'',rows:spec.rows};made.push(f);return f;}
for(const p of c.psc.filter(p=>!p.ceased)){const oldP=active.find(x=>x.id===p.id);const recorded=filing(Number(oldP.share)===0&&Number(p.share)>0?'REG-PSC1':'REG-PSC2','Persons with significant control','Shareholding and voting details of '+p.name,[['Holder',p.name],['Type',p.kind],['Previous equity',oldP.share+'%'],['Equity',p.share+'%'],['Class A founder',(p.classA||0)+'%'],['Class B ordinary',(p.classB||0)+'%'],['Effective voting power',calc.holders[p.id].votes+'%'],...(calc.holders[p.id].delegations||[]).map(d=>['Voting delegation',d.name+': '+d.votes+'% of company votes']),...(calc.holders[p.id].receivedFrom||[]).map(d=>['Voting received from',d.name+': '+d.votes+'% of company votes'])]);if(Number(oldP.share)===0&&Number(p.share)>0&&!p.notificationFiling)p.notificationFiling=recorded.id;}
filing('REG-RES','Resolution','Owner-authorised equity and voting allocation; founder minimum changed to 51%',[['Previous founder minimum',String(before.founderVotingMinimum||75)+'%'],['New founder minimum','51% collectively; Charlie Livsey 25.5% and HN Group 25.5%'],['Parent company',parent.legalName],['Voting instructions','Community Organisation delegates half of its 29% voting entitlement to Dion McKew and half to Evan Strong; earlier contrary delegations revoked'],['Founder transfers','Class A may be retained on transfer with written founder consent, or converted to ordinary Class B']]);
filing('REG-CAP','Capital','Statement of capital and voting rights following owner instruction',[['Class A founder equity','51%'],['Class B ordinary equity','49%'],['Total equity','100%'],['Total voting rights','100%'],...c.psc.filter(p=>!p.ceased).map(p=>[p.name,p.share+'% equity; '+calc.holders[p.id].votes+'% voting power'])]);s.audit(actor,'capital.owner-allocation',c.slug+' '+reference);s.save();
const after=JSON.parse(fs.readFileSync(file));for(const name of ['customers','requests','submissions'])assert.deepEqual(after[name],old[name]);assert.ok(old.filings.every(f=>after.filings.some(g=>JSON.stringify(f)===JSON.stringify(g))));assert.ok(after.companies.every(c=>c.shareModel==='founder75'));for(const oldC of old.companies.filter(c=>c.slug!=='horizon-network')){const updated=after.companies.find(c=>c.slug===oldC.slug);assert.deepEqual(updated.psc.map(p=>[p.id,p.name,p.share,p.ceased]),oldC.psc.map(p=>[p.id,p.name,p.share,p.ceased]));}return {reference,holders:c.psc.filter(p=>!p.ceased).map(p=>({id:p.id,name:p.name,equity:Number(p.share),classA:Number(p.classA||0),classB:Number(p.classB||0),votes:calc.holders[p.id].votes})),delegations:c.votingDelegations,filings:after.filings.filter(f=>!old.filings.some(x=>x.id===f.id)).map(f=>({id:f.id,slug:f.company,file:f.file,description:f.description}))};
}catch(e){fs.writeFileSync(file,raw);for(const file of fs.readdirSync(filesDir))if(!priorFiles.has(file))fs.rmSync(path.join(filesDir,file));throw e;}}
module.exports={apply};if(require.main===module){try{console.log(JSON.stringify(apply(...process.argv.slice(2)),null,2));}catch(e){console.error(e.stack);process.exitCode=1;}}
